ProjectALife.DialogueShards["scenes_any_8"] = {
{"fw_ld4_quick_l_0025","any",2,"reg=military,elite",{1,"Is the coffee strong?",2,"It could stand a spoon in it",1,"Perfect",2,"It's mostly grounds"}},
{"fw_ld4_quick_l_0026","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"You got a plan B?",2,"I got a plan Z",1,"What's plan Z?",2,"Run, shout 'sorry', run more"}},
{"fw_ld4_quick_l_0027","any",2,"reg=outlaw,raider,gang,club,crime,prison|hour=16,5",{1,"Boss says we eat first tonight",2,"Why?",1,"Because there's not enough for tomorrow anyway",2,"Smart boss"}},
{"fw_ld4_quick_l_0028","any",2,"reg=family",{1,"Come to the table, children",2,"What are we having?",1,"Hope and beans",2,"Hope's my favorite",1,"Mine too, dear, mine too"}},
{"fw_ld4_quick_l_0029","any",2,"reg=family",{1,"Mama, I lost my tooth",2,"Oh, let me see",1,"Here, in my hand",2,"Put it under the pillow, the tooth fairy is still on duty"}},
{"fw_ld4_quick_m_0001","any",2,"reg=civilian,family,worker,rescue",{1,"Come sit by me",2,"I'm fine over here",1,"Please",2,"Fine, scoot over"}},
{"fw_ld4_quick_m_0002","any",2,"reg=civilian,family,worker,rescue",{1,"You asleep?",2,"No",1,"Me neither",2,"Want to talk?",1,"Just keep breathing loud, so I know you're there"}},
{"fw_ld4_quick_m_0003","any",2,"reg=civilian,family,worker,rescue",{1,"How's your stomach?",2,"Empty",1,"Mine too",2,"Want to sit and be empty together?"}},
{"fw_ld4_quick_m_0004","any",2,"reg=civilian,family,worker,rescue",{1,"Think they miss us?",2,"Who?",1,"Everyone, all the people we left",2,"Every minute"}},
{"fw_ld4_quick_m_0005","any",2,"reg=civilian,family,worker,rescue",{1,"Did I ever say thank you?",2,"For what?",1,"For pulling me out",2,"You said it twice, stop"}},
{"fw_ld4_quick_m_0006","any",2,"reg=civilian,family,worker,rescue",{1,"You sure you're alright?",2,"I'm alive",1,"I meant how are you really",2,"It's what I've got"}},
{"fw_ld4_quick_m_0007","any",2,"reg=civilian,family,worker,rescue",{1,"I think I'm losing my mind",2,"Not yet",1,"And how would I know?",2,"You're still asking"}},
{"fw_ld4_quick_m_0008","any",2,"reg=civilian,family,worker,rescue",{1,"Hey, I love you guys",2,"Where's that coming from?",1,"Nowhere, everywhere, I just wanted to say it",2,"We love you too, you idiot"}},
{"fw_ld4_quick_m_0009","any",2,"reg=civilian,family,worker,rescue|world=building",{1,"Know what I miss?",2,"What?",1,"Doing nothing, absolutely nothing, on a couch",2,"With a remote",1,"With a remote and a bag of chips"}},
{"fw_ld4_quick_m_0010","any",2,"reg=civilian,family,worker,rescue",{1,"Whose shoes are those?",2,"Mine",1,"They're too small",2,"They're a size and a half too small, I'm aware"}},
{"fw_ld4_quick_m_0011","any",2,"reg=civilian,family,worker,rescue",{1,"What's the first thing you'll do if we find a phone?",2,"Call my mother",1,"What will you say?",2,"I'll say 'I'm okay', and then I'll say it again, and again"}},
{"fw_ld4_quick_m_0012","any",2,"reg=civilian,family,worker,rescue",{1,"Are we the last ones?",2,"Don't think so",1,"Why'd you say that?",2,"Because people like us don't give up quietly"}},
{"fw_ld4_quick_m_0013","any",2,"reg=civilian,family,worker,rescue",{1,"Say something funny",2,"I'm hungry",1,"That's not funny",2,"It's funny to my stomach"}},
{"fw_ld4_quick_m_0014","any",2,"reg=civilian,family,worker,rescue",{1,"Be careful with that",2,"It's just a spoon",1,"It's our only spoon",2,"Then I'll treat it like a baby"}},
{"fw_ld4_quick_m_0015","any",2,"reg=civilian,family,worker,rescue",{1,"It's weird how quiet it is",2,"Quiet like a held breath",1,"How long can the world hold its breath?",2,"Hopefully until the end of the day"}},
{"fw_ld4_quick_m_0016","any",2,"reg=civilian,family,worker,rescue",{1,"I'm too tired to be sad",2,"That's a blessing",1,"Is it?",2,"It's a break"}},
{"fw_ld4_quick_m_0017","any",2,"reg=civilian,family,worker,rescue",{1,"Are you afraid of dying?",2,"Of dying alone",1,"Then you won't die alone",2,"Is that a promise?",1,"It's the only one I can make"}},
{"fw_ld4_quick_m_0018","any",2,"reg=civilian,family,worker,rescue",{1,"Eat something",2,"I'm not hungry",1,"Eat anyway",2,"Fine, a bite",1,"Two bites"}},
{"fw_ld4_quick_m_0019","any",2,"reg=civilian,family,worker,rescue",{1,"What do you want for your birthday?",2,"A cake",1,"What kind?",2,"Any kind, with any frosting, even bad frosting"}},
{"fw_ld4_quick_m_0020","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"Will you tell me when it's safe?",2,"I will",1,"Even if I'm sleeping?",2,"Especially if you're sleeping"}},
{"fw_ld4_quick_m_0021","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"I don't think I'm cut out for this",2,"Nobody is",1,"But you seem to be",2,"I'm cut out for pretending"}},
{"fw_ld4_quick_m_0022","any",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"How many more nights?",2,"As many as it takes",1,"That's no answer",2,"It's the only honest one"}},
{"fw_ld4_quick_m_0023","any",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"I got you a present",2,"What is it?",1,"Nothing, I'm broke",2,"That is the best present, thank you"}},
{"fw_ld4_quick_m_0024","any",2,"reg=law,swat",{1,"You still got your badge?",2,"In my pocket",1,"Why not on your shirt?",2,"Makes me a target, but I keep it close"}},
{"fw_ld4_quick_m_0025","any",2,"reg=law,swat",{1,"Think we'll ever clock out?",2,"Someday",1,"Then what?",2,"Then I'll sleep for a week"}},
{"fw_ld4_quick_m_0026","any",2,"reg=military,elite",{1,"Think of something nice",2,"Like what?",1,"A beach, a drink, a hammock",2,"With a book",1,"With no rank, no orders, just sand"}},
{"fw_ld4_quick_m_0027","any",2,"reg=military,elite",{1,"Sir, you haven't slept",2,"I'll sleep when it's over",1,"Sir, with respect, that's how people die",2,"Noted, Private, wake me in an hour"}},
{"fw_ld4_quick_m_0028","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"This kid's getting on my nerves",2,"He's scared",1,"He's loud",2,"He's scared and loud, like all of us"}},
{"fw_ld4_quick_m_0029","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"What if the boss dies?",2,"Then we fight over his boots",1,"That's it?",2,"That's it, they're nice boots"}},
{"fw_ld4_quick_m_0030","any",2,"reg=family",{1,"Mama, will it always be like this?",2,"No, baby",1,"How come?",2,"Because nothing lasts, not even the bad"}},
{"fw_ld4_quick_m_0031","any",2,"reg=family",{1,"Papa, are you scared?",2,"Sometimes",1,"Me too",2,"Then we're the same, you and me"}},
{"fw_ld4_smalltalk_a_0001","any",2,"reg=civilian,family,worker,rescue",{1,"What's the first thing you're gonna do when this is over?",2,"Hot shower, hands down, a long one",1,"I'd go straight to Dairy Queen, a Blizzard, the big size",2,"Oh my God, don't, I can almost taste it",1,"Reese's, with the cookie dough on top...",2,"Stop it, stop it, I'm gonna cry"}},
{"fw_ld4_smalltalk_a_0002","any",2,"reg=civilian,family,worker,rescue",{1,"Do you remember your phone number?",2,"At the old house? 502-555-0143, why?",1,"Just checking if I still remember mine, I do, 502-555-0188",2,"Nobody to call, though, is there",1,"Nope, but it's nice to know the number"}},
{"fw_ld4_smalltalk_a_0003","any",2,"reg=civilian,family,worker,rescue",{1,"You ever think about the Derby?",2,"First Saturday in May, my daddy used to bet a dollar on the gray horse",1,"Every year?",2,"Every year, never won once, kept betting anyway",1,"God, I miss silly stuff like that"}},
{"fw_ld4_smalltalk_a_0004","any",2,"reg=civilian,family,worker,rescue",{1,"I found a pack of gum in my coat, still sealed",2,"You're kidding, give me one",1,"Split it? Two sticks each?",2,"Sure... oh wow, Juicy Fruit, it's like being a kid again",1,"Chew it slow, it's all we've got"}},
{"fw_ld4_smalltalk_a_0005","any",2,"reg=civilian,family,worker,rescue",{1,"Mama used to say, 'Don't go out looking for trouble'",2,"Mine said, 'Don't come home crying'",1,"Did you listen?",2,"Not once, not one single time, and look where it got me",1,"Same, honey, same"}},
{"fw_ld4_smalltalk_a_0006","any",2,"reg=civilian,family,worker,rescue",{1,"What's your name, by the way?",2,"Dale, you?",1,"Brenda, we've been walking together two days, and I never asked",2,"I never asked either, funny, huh?",1,"Yeah, funny what you notice when everything else is gone"}},
{"fw_ld4_smalltalk_a_0007","any",2,"reg=civilian,family,worker,rescue|world=vehicle",{1,"I keep dreaming about the school bus",2,"What about it?",1,"It stops in front of my house, and all the kids get off, and they're fine, they're all fine",2,"...that's a nice dream",1,"Yeah, then I wake up"}},
{"fw_ld4_smalltalk_a_0008","any",2,"reg=civilian,family,worker,rescue",{1,"Is it just me, or do your feet hurt more than anything else?",2,"My feet, my back, my knees, my head, everything",1,"But mostly the feet",2,"Mostly the feet, yeah, I'd trade a kidney for new socks"}},
{"fw_ld4_smalltalk_a_0009","any",2,"reg=civilian,family,worker,rescue",{1,"What was the last movie you saw?",2,"Jurassic Park, with my son, in June",1,"Oh, I wanted to see that, was it good?",2,"He covered his eyes the whole time, and loved it, made me promise to take him again",1,"...did you?",2,"No, we didn't get the chance"}},
{"fw_ld4_smalltalk_a_0010","any",2,"reg=civilian,family,worker,rescue|world=building",{1,"You think they'll ever get the lights back on?",2,"Somebody will, someday",1,"I used to complain about the electric bill",2,"I'd pay triple, right now, just to see a refrigerator light up"}},
{"fw_ld4_smalltalk_a_0011","any",2,"reg=civilian,family,worker,rescue",{1,"Say something nice, I need it",2,"Your hair doesn't look that bad",1,"Gee, thanks, that's insulting",2,"Fine- you're good company and you carry cans real well",1,"Better, thanks"}},
{"fw_ld4_smalltalk_a_0012","any",2,"reg=civilian,family,worker,rescue",{1,"How long have you been alone?",2,"Since the second day",1,"That's a long time",2,"It's long when you can't sleep, and shorter when you can't stop running",1,"Well, you're not alone now"}},
{"fw_ld4_smalltalk_a_0013","any",2,"reg=civilian,family,worker,rescue|world=rain",{1,"I used to hate Mondays",2,"Everybody hated Mondays",1,"Now I'd give anything for a Monday, a boring, rainy, traffic-jam Monday",2,"With a boss yelling at me about a spreadsheet",1,"God, yes, yell at me about the spreadsheet"}},
{"fw_ld4_smalltalk_a_0014","any",2,"reg=civilian,family,worker,rescue",{1,"Can I tell you a secret?",2,"Sure",1,"I'm not as brave as I look",2,"You look terrified, actually",1,"...oh, good, so it's working then"}},
{"fw_ld4_smalltalk_a_0015","any",2,"reg=civilian,family,worker,rescue",{1,"Everyone in this group has a nickname except me",2,"That's not true, we call you 'Mom'",1,"I'm 26!",2,"And you make us wash our hands before eating, so, Mom"}},
{"fw_ld4_smalltalk_a_0016","any",2,"reg=civilian,family,worker,rescue",{1,"Don't look now, but that guy has been following us all day",2,"The one with the limp?",1,"Yeah, what do we do?",2,"...ask him if he wants some beans?",1,"Are you serious?",2,"Look at him, he's more scared than we are"}},
{"fw_ld4_smalltalk_a_0017","any",2,"reg=civilian,family,worker,rescue|hour=6,11",{1,"Did you sleep?",2,"A little, you?",1,"Not a wink, I counted every noise",2,"Next time wake me, I'll count the second half",1,"Deal, shake on it, no, wait, germs, nod on it"}},
{"fw_ld4_smalltalk_a_0018","any",2,"reg=civilian,family,worker,rescue|hour=6,11",{1,"Smells like coffee, am I dreaming?",2,"Nope, I found a jar of instant behind the shelves, one cup, we share",1,"You're an angel",2,"I'm a hoarder, but thanks"}},
{"fw_ld4_smalltalk_a_0019","any",2,"reg=civilian,family,worker,rescue|hour=6,11",{1,"Morning, sunshine",2,"Don't, I'm not ready, I'm not even awake",1,"It's the best part of the day, nobody's dead yet",2,"...that's weirdly comforting, give me a minute"}},
{"fw_ld4_smalltalk_a_0020","any",2,"reg=civilian,family,worker,rescue|hour=21,4",{1,"You can't sleep either?",2,"Every time I close my eyes I hear scratching",1,"Same, let's just sit here, talk about nothing",2,"Like what?",1,"Anything, tell me what you had for breakfast the day before all this",2,"Cinnamon toast, with too much butter, my mother's recipe"}},
{"fw_ld4_smalltalk_a_0021","any",2,"reg=civilian,family,worker,rescue|hour=21,4",{1,"Who's on watch?",2,"Me, go back to sleep",1,"I can't, I just keep thinking",2,"About what?",1,"About the people I left behind",2,"...yeah, me too, me too"}},
{"fw_ld4_smalltalk_a_0022","any",2,"reg=civilian,family,worker,rescue|hour=21,4",{1,"Shh, did you hear that?",2,"Hear what?",1,"Never mind, probably nothing",2,"'Probably nothing' - that's what everybody says right before it's something",1,"Sorry, sorry, I'll shut up"}},
{"fw_ld4_smalltalk_a_0023","any",2,"reg=family",{1,"Come here, let me fix your collar",2,"Mama, I'm fine",1,"You're a mess, hold still, there",2,"Now I look like a baby",1,"You'll always be my baby, deal with it"}},
{"fw_ld4_smalltalk_a_0024","any",2,"reg=family",{1,"Grandpa, tell me about the old days",2,"Which ones? The good ones or the bad ones?",1,"The good ones, please",2,"Well, there was a Fourth of July in '52, we had a watermelon as big as a washtub...",1,"Go on, what happened next?"}},
{"fw_ld4_smalltalk_a_0025","any",2,"reg=family",{1,"Papa, are we going to be okay?",2,"'Course we are, little man",1,"You promise?",2,"I promise we'll stick together, how's that?",1,"...okay, that's good enough"}},
{"fw_ld4_smalltalk_a_0026","any",2,"reg=family",{1,"Eat your beans",2,"I don't like beans",1,"Nobody likes beans, eat them anyway",2,"Can I at least have ketchup?",1,"...we're out, but I'll let you pretend",2,"Thanks, Mama"}},
{"fw_ld4_smalltalk_a_0027","any",2,"reg=family",{1,"Did you brush your teeth?",2,"There's no toothpaste",1,"Salt, baking soda, whatever you got",2,"That's gross",1,"So are cavities, now go"}},
{"fw_ld4_smalltalk_a_0028","any",2,"reg=family",{1,"Mamaw's quilt is still the warmest thing I own",2,"I remember her stitching that",1,"Every square from somebody's old dress",2,"There's a piece of mine in there, the blue gingham",1,"I know, I look at it every night"}},
{"fw_ld4_smalltalk_b_0001","any",2,"reg=law,swat",{1,"You eat yet?",2,"A granola bar, half a granola bar",1,"Where's the other half?",2,"In my pocket, saving it for a worse day",1,"Brother, today IS the worse day"}},
{"fw_ld4_smalltalk_b_0002","any",2,"reg=law,swat",{1,"Remember when the worst thing in this job was a drunk and disorderly?",2,"Friday nights at the Tastee-Freez, yeah",1,"I'd give my pension to arrest one more drunk",2,"You'd give your pension to hear him complain about the coffee"}},
{"fw_ld4_smalltalk_b_0003","any",2,"reg=law,swat",{1,"Chief used to say, 'Write it all down'",2,"I wrote it all down, I've got two notebooks",1,"Anything useful?",2,"Mostly dates, and names of people I couldn't save",1,"...that's useful, Ray, that's the most useful thing in the county"}},
{"fw_ld4_smalltalk_b_0004","any",2,"reg=law,swat|world=building",{1,"My wife keeps the porch light on",2,"You told me she was in Louisville",1,"She is, I can't stop picturing it, a light on in an empty house",2,"Ah hell, Danny, come here"}},
{"fw_ld4_smalltalk_b_0005","any",2,"reg=law,swat",{1,"What's the count?",2,"Eleven rounds, three flares, one working radio",1,"That's not much",2,"It's a lot more than yesterday, if you think about it",1,"Don't make me think, I'm barely holding together"}},
{"fw_ld4_smalltalk_b_0006","any",2,"reg=law,swat",{1,"Roll call, 0600, I'll do the honors",2,"There's four of us",1,"Four's still a roll call, Deputy",2,"Yes sir, Deputy Cole present",1,"Deputy Harmon present, Deputy... Reeves?",2,"...he's not here, sir",1,"...no, no he's not, mark him absent"}},
{"fw_ld4_smalltalk_b_0007","any",2,"reg=law,swat",{1,"You ever fire that thing before the ninth?",2,"Qualified every year, never once at a person",1,"And now?",2,"Now I qualify every day, at 'em",1,"How's the score?",2,"Don't ask"}},
{"fw_ld4_smalltalk_b_0008","any",2,"reg=law,swat",{1,"Gotta say, you handle yourself better than I expected",2,"Is that a compliment?",1,"Take it before I change my mind",2,"Thanks, Sarge, I think"}},
{"fw_ld4_smalltalk_b_0009","any",2,"reg=law,swat",{1,"Did you hear the man on the radio last night?",2,"The one who plays the old country songs?",1,"Yeah, he played one of Daddy's favorites, I had to step outside",2,"Which one?",1,"'He Stopped Loving Her Today', go ahead and laugh",2,"I'm not laughing"}},
{"fw_ld4_smalltalk_b_0010","any",2,"reg=law,swat|world=trees",{1,"Hey, you remember Mrs. Hadley's cat?",2,"Biscuit, up the tree again, we got him down three times",1,"I'd give anything to get that cat out of a tree right now",2,"Me too, Dan, me too"}},
{"fw_ld4_smalltalk_b_0011","any",2,"reg=military,elite",{1,"Sergeant says move at 0400",2,"Of course he does, nobody ever moves at noon",1,"Noon is for the living",2,"Then we're doing it wrong"}},
{"fw_ld4_smalltalk_b_0012","any",2,"reg=military,elite",{1,"What's your MOS?",2,"11 Bravo, infantry, you?",1,"92 Golf, cook",2,"God, I've been missing you for days",1,"Everyone says that, once they're hungry"}},
{"fw_ld4_smalltalk_b_0013","any",2,"reg=military,elite",{1,"Corporal, you ever think about what we're doing?",2,"Every night",1,"And?",2,"And I think about my orders, because that's easier"}},
{"fw_ld4_smalltalk_b_0014","any",2,"reg=military,elite",{1,"You write your folks?",2,"Every day, in my head",1,"How's that working out?",2,"They never write back, but they don't criticize my handwriting"}},
{"fw_ld4_smalltalk_b_0015","any",2,"reg=military,elite",{1,"Private! What do I always say first?",2,"Keep your weapon clean, Sergeant",1,"What's the second?",2,"Keep your friends alive, Sergeant",1,"Good, now do both"}},
{"fw_ld4_smalltalk_b_0016","any",2,"reg=military,elite",{1,"Anyone got a smoke?",2,"Last one, here, share it with Dobbs",1,"Dobbs is dead",2,"...I know, I forgot, just... hold it for him anyway"}},
{"fw_ld4_smalltalk_b_0017","any",2,"reg=military,elite",{1,"You scared?",2,"Always",1,"Doesn't show",2,"That's the trick, you fake it until you're not faking it",1,"Does that work?",2,"Never has, but it keeps the others calm"}},
{"fw_ld4_smalltalk_b_0018","any",2,"reg=military,elite",{1,"Back home I coached little league",2,"Which position?",1,"Wherever the kids who couldn't catch needed to be",2,"Sounds like the best job in the world",1,"It was, kid, it was"}},
{"fw_ld4_smalltalk_b_0019","any",2,"reg=military,elite",{1,"Lieutenant says the Guard's going to relieve us",2,"When?",1,"He didn't say",2,"So never",1,"...probably never, yeah"}},
{"fw_ld4_smalltalk_b_0020","any",2,"reg=military,elite",{1,"Hey, Sarge, are you married?",2,"Twenty-two years, her name's Linda, she hates the Army",1,"She sounds smart",2,"She is, she told me not to re-up, and I did anyway, idiot"}},
{"fw_ld4_smalltalk_b_0021","any",2,"reg=law,swat|day=10,3650",{1,"Station's gone quiet",2,"Dead, it's dead, I'd take sirens over this",1,"You hate sirens",2,"I hate being alone with my thoughts more"}},
{"fw_ld4_town_a_0001","any",2,"reg=civilian,family,worker,rescue",{1,"Did you see the new people at the edge of town?",2,"Refugees, I think, from Louisville",1,"How many?",2,"Maybe twenty, with kids, carrying everything they own",1,"We should do something",2,"Like what? We can barely feed ourselves",1,"I know, I know, but they looked so tired"}},
{"fw_ld4_town_a_0002","any",2,"reg=civilian,family,worker,rescue|hour=16,5",{1,"Somebody should tell them about the curfew",2,"What curfew?",1,"The one the deputy keeps shouting about, after dark everyone stays in",2,"Does anybody follow it?",1,"The ones who want to stay alive do"}},
{"fw_ld4_town_a_0003","any",2,"reg=civilian,family,worker,rescue",{1,"Anybody want to trade? I've got batteries",2,"What do you need?",1,"Anything salty, I'm starving for salt",2,"I've got a jar of pickles",1,"Pickles?! Pickles are PERFECT"}},
{"fw_ld4_town_a_0004","any",2,"reg=civilian,family,worker,rescue",{1,"The deputy says we need volunteers for a watch rotation",2,"How many?",1,"Eight, four on, four off",2,"I'll do it, I'm not sleeping anyway",1,"Thank you, you're a lifesaver"}},
{"fw_ld4_town_a_0005","any",2,"reg=civilian,family,worker,rescue",{1,"What's the word from the Fort?",2,"Nothing, nobody's heard anything",1,"They were supposed to send help",2,"They were supposed to do a lot of things"}},
{"fw_ld4_town_a_0006","any",2,"reg=civilian,family,worker,rescue",{1,"I wonder how many people are left in the county",2,"A few thousand, maybe",1,"Out of how many?",2,"Forty-something, thousand, forty-something thousand",1,"...that's not a number I want to think about"}},
{"fw_ld4_town_a_0007","any",2,"reg=civilian,family,worker,rescue|hour=6,11",{1,"Roll call, everyone who's still here, say your name",2,"Dale",1,"Brenda",2,"Chuck, Linda, Mr. Haskins, Earl, little Tommy",1,"Seven, we're seven, one more than yesterday",2,"Welcome to the new guy, whoever he is"}},
{"fw_ld4_town_a_0008","any",2,"reg=civilian,family,worker,rescue|hour=21,4",{1,"Curfew's in an hour",2,"Who counts the hours?",1,"The deputy, he's got the only working watch",2,"Of course he does",1,"Don't be bitter, be grateful, at least he's keeping time"}},
{"fw_ld4_town_a_0009","any",2,"reg=law,swat",{1,"Citizens keep asking when the curfew ends",2,"Tell them it doesn't",1,"They won't like that",2,"They don't have to like it, they just have to survive it"}},
{"fw_ld4_town_a_0010","any",2,"reg=law,swat|world=door",{1,"The sheriff's office is packed to the gills",2,"Who's staying?",1,"Mostly families, a few vets, a couple of strays",2,"Keep the strays near the door, I don't trust strays"}},
{"fw_ld4_town_a_0011","any",2,"reg=law,swat",{1,"Another group came in from the north, wounded",2,"How many?",1,"Six, two critical",2,"Where's the medic?",1,"Out on a call, I'll find her"}},
{"fw_ld4_town_a_0014","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"There's a new bunch of survivors rolling through town",2,"Anything worth taking?",1,"Let's see what they've got, maybe food, maybe ammo",2,"And if they fight?",1,"Then we win, we always win"}},
{"fw_ld4_town_a_0015","any",2,"reg=family",{1,"I'm not going to the shelter",2,"Why not?",1,"Too many strangers, too many sick, too many scared",2,"Where, then?",1,"Home, our home, it's still ours, whatever they say"}},
{"fw_ld4_town_a_0016","any",2,"reg=family|world=cars",{1,"Did the Guard say when the buses are coming?",2,"Tomorrow, they said tomorrow",1,"They said that yesterday",2,"...and the day before, honey, hush now"}},
{"king_scene_missing_word","any",2,"mood=calm",{1,"I had something to ask you. Lost it completely",2,"Was it important?",1,"Probably not. I would've looked more worried",2,"Tell me when it comes back",1,"Yeah. Thanks for not making it a big thing"}},
{"king_scene_not_a_test","any",2,"mood=warm",{1,"You don't have to have the right answer every time I talk",2,"I never know when somebody is testing me anymore",1,"This time I'm just talking",2,"All right. I can try that",1,"Good. I wasn't doing especially well with the questions either"}},
{"king_scene_apology","any",2,"mood=calm",{1,"If I get short with you, tell me",2,"Will that make it worse?",1,"Maybe for a second. I'd still rather know",2,"All right. Same goes for me",1,"Deal. We'll be difficult people honestly"}},
{"king_scene_good_memory","any",2,"mood=sad",{1,"I get annoyed when I remember something good",2,"Why annoyed?",1,"Feels like something I can't afford to think about",2,"You don't have to throw it away",1,"I know. I'm trying to believe that part"}},
{"king_scene_small_talk","any",2,"mood=warm",{1,"What did you used to talk about when there was nothing to talk about?",2,"Mostly other people. I wasn't very interesting",1,"I complained about being bored",2,"We could complain about that. For practice",1,"Yeah. I'm already feeling better about it"}},
{"king_scene_permission_quiet","any",2,"mood=calm",{1,"I'm not good company every minute",2,"Didn't ask you to be",1,"I keep thinking I owe people something for staying",2,"You can just be here for a bit",1,"That sounds nice. Strange, but nice"}},
{"king_scene_something_funny","any",2,"mood=funny",{1,"I thought of something funny and immediately forgot why",2,"At least you had a good second",1,"I was going to share it. Very generous of me",2,"I'll remember the gesture",1,"Somebody ought to. I clearly won't"}},
{"king_scene_wrong_confidence","any",2,"mood=grim",{1,"If I say I'm sure, ask me how I know",2,"You think you might lie?",1,"I think I might want something to be true too badly",2,"Fair enough. You ask me too",1,"All right. I'd rather be annoyed than wrong about something that matters"}},
{"king_scene_ordinary_request","any",2,"mood=warm",{1,"Tell me something ordinary about yourself",2,"I used to check the same pocket twice for my keys",1,"That's properly ordinary",2,"What were you expecting?",1,"Nothing. That's why I asked. I wanted something that wasn't terrible"}},
{"king_scene_tomorrow_word","any",2,"mood=sad",{1,"I nearly said remind me tomorrow",2,"You still can",1,"Feels like tempting something",2,"It's only a word. We're allowed to want another day",1,"Then remind me tomorrow. About this"}},
{"s11_a01_gate_shut_since_august_001","any",3,"reg=civilian,family|tmp=seasoned|day=40,400|mood=grim|world=vehicle",{1,"I remember Kemble keeping that gate shut. Said at least his kids were fed",2,"You gave him that?",1,"I gave him that. Didn't ask where the three fellas from the blue van went",3,"Nobody asked. That was the arrangement"}},
{"s11_a01_nobody_said_boo_002","any",3,"reg=civilian,family|tmp=seasoned|day=30,400|mood=grim",{1,"He shot Ferrell in the yard before he turned, right there by the pump",2,"Ferrell was two hours off it, everybody knew that",1,"Sure, and not one of us said boo - that's the part sits on me",3,"You want to say boo, go say it to him",1,"No, I want to say it here, where it don't cost me nothing"}},
{"s11_a01_back_room_list_003","any",2,"reg=civilian|tmp=seasoned|day=40,400|mood=angry|world=door",{1,"Started out Sowder's cousin gets the back room 'cause she was expecting",2,"She had that baby in October",1,"There's a list on the door now - four names, I ain't on it and neither are you"}},
{"s11_a01_counts_the_cans_004","any",2,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=grim|world=vehicle",{1,"He let Sowder stay on after the truck business, everybody said that was decent of him",2,"It was decent",1,"Now Sowder counts the cans and reads the list out - funny how that landed"}},
{"s11_a01_loretta_is_right_005","any",2,"reg=civilian,family|tmp=seasoned|day=30,400|mood=sad|world=road",{1,"Loretta's right about that well, she's right and she's gonna get put on the road for it",2,"Both them things can be true",1,"They are true, same time, same breath, that's what I can't get past"}},
{"s11_a01_two_men_one_doorway_006","any",3,"reg=rescue|tmp=seasoned,veteran|day=20,120|hour=16,5|mood=angry|world=door",{1,"We got a deputy and a Guard sergeant both giving orders about the same doorway",2,"So pick one",1,"I run a fire company, I don't get to pick - but somebody's getting shot over a door",3,"Then you pick, Cap, today, before dark, and say it loud"}},
{"s11_a01_waiting_on_please_007","any",3,"reg=worker,civilian|tmp=seasoned|day=30,400|mood=angry",{1,"He knows where that diesel's buried, has done three weeks",2,"Then ask him",1,"That's just how it works, he's waiting on us to come say please",3,"So somebody say please and let's get the pump turning",1,"You say it, I've said please to that man twice this month already"}},
{"s11_a01_who_told_him_008","any",2,"reg=civilian,family|tmp=seasoned|day=40,400|mood=calm",{1,"He don't care about the coffee, son",2,"It was half a can",1,"He cares who came and told him about the coffee - that's what he was buying"}},
{"s11_a01_watch_his_hands_009","any",2,"reg=civilian,worker|tmp=seasoned|day=30,400|mood=fear",{1,"Watch his hands next time he reads the watch list out",2,"His hands?",1,"That's all I'm saying - watch his hands, then tell me that man's calm"}},
{"s11_a01_tree_falls_on_him_010","any",3,"reg=civilian,family|tmp=seasoned|day=40,400|mood=funny|world=trees",{1,"Say a tree comes down on Kemble tomorrow - who reads the list?",2,"Don't talk like that",1,"I'm asking a real question - anybody? No? Great - good talk",3,"Ada keeps the book - Ada'd read it",1,"Ada'd read it fair and we'd all starve fair, both them things"}},
{"s11_a01_corn_under_the_porch_011","any",4,"reg=civilian,family|tmp=seasoned|day=40,400|mood=angry|world=building",{1,"Sixty pound of shelled corn under the Kelso porch - Sacked and dry",2,"Then we tell him and we get our cut off the top",3,"Or we don't tell him and we eat corn",4,"And when he finds out, and he will, we're the ones stole from the camp",1,"Hands, then - right now, I ain't carrying this one on my own"}},
{"s11_a01_pleasant_as_pie_012","any",2,"reg=worker|tmp=seasoned|day=30,400|mood=funny",{1,"Pump quits again, he'll come find me pleasant as pie",2,"Wasn't so pleasant Tuesday",1,"Tuesday the pump was running, that's the entire difference in the man"}},
{"s11_a01_talk_to_ruthie_013","any",2,"reg=family,civilian|tmp=fresh,seasoned|day=30,400|mood=grim",{1,"Go talk to Ruthie, he listens to Ruthie",2,"Ruthie's the one told him about the coffee",1,"Huh, alright, scratch that then"}},
{"s11_a01_color_in_her_face_014","any",2,"reg=family|tmp=seasoned|day=60,400|mood=sad",{1,"Callie's put weight back on since we come here, got color in her face again",2,"I know it",1,"So he does something I hate and I look at her face and I shut my mouth",2,"Well, she's a mother",1,"It's something, I ain't decided what yet"}},
{"s11_a01_bad_hip_and_a_girl_015","any",2,"reg=worker,civilian|tmp=seasoned|day=40,400|mood=grim",{1,"You think I enjoy reading that list out loud?",2,"I think you enjoy the back room",1,"I got a bad hip and a girl that's nine - yeah, I like the back room fine"}},
{"s11_a01_hung_that_ladder_016","any",3,"reg=civilian,family|tmp=seasoned|day=60,400|mood=grim|world=stairs",{1,"We hauled that fella out the ditch on Zink Road in September - fed him, splinted his arm",2,"And?",1,"He come back with six men and a list of what we had and where we kept it",3,"He knew where the ladder hung, he hung that ladder up himself"}},
{"s11_a01_three_rifles_017","any",2,"reg=civilian,worker|tmp=seasoned|day=40,400|mood=grim",{1,"Only three rifles go out the gate and he picks who carries 'em",2,"He picks the three that won't turn one on him",1,"That's what I said, you said it plainer"}},
{"s11_a01_want_him_wrong_once_018","any",2,"reg=civilian,family|tmp=seasoned|day=60,400|mood=sad",{1,"Hard part ain't that he's cruel",2,"What's the hard part",1,"He's been right, every hard call since August, nobody's died that he said wouldn't",2,"So you want him wrong one time",1,"God forgive me, a little - once - something small"}},
{"s11_a01_four_days_unlatched_019","any",4,"reg=civilian,family|tmp=seasoned|day=60,400|mood=calm",{1,"He's gone till Thursday, four days with nobody stood over us",2,"Four days is when a place like this decides what it is",3,"Or it's four days and then he comes back and asks us what we decided",4,"I ain't deciding nothing, I'm gonna sleep with my door unlatched, is all",1,"Unlatched - you hear that? That's what he's got on us"}},
{"s11_a01_write_the_temperature_020","any",2,"reg=rescue|tmp=seasoned|day=30,400|mood=angry|world=building",{1,"He wants me to sign that Sowder's fit for watch - Sowder's running a hundred and one",2,"Then don't sign it",1,"Then we're a man short on the wall and that's on my name too",2,"Write the temperature and the date - in ink",1,"I'm a nurse, not a lawyer"}},
{"s11_a01_boy_stands_like_him_021","any",2,"reg=family|tmp=seasoned|day=60,400|mood=grim",{1,"My boy's took to standing like Kemble - hands hooked on his belt, like that",2,"He's eleven",1,"Asked me could he carry the list around, I said no and he sulked all evening"}},
